export function formatInferenceSpend(summary: CostSummary | undefined): string {
  if (!summary) return "—";
  if (summary.unpricedEventCount == null || summary.reportedEventCount == null) {
    return `已记录 ${formatCents(summary.spendCents)}（报价状态未知）`;
  }
  const unpriced = Math.max(0, summary.unpricedEventCount - (summary.unpricedSubscriptionEventCount ?? 0));
  if (summary.reportedEventCount === 0 && summary.unpricedEventCount > 0) {
    return unpriced > 0 ? "未定价" : "订阅内含";
  }
  if (unpriced > 0) return `${formatCents(summary.spendCents)} + 未定价用量`;
  if (summary.unpricedEventCount > 0) return `${formatCents(summary.spendCents)} · 另有订阅内含`;
  return formatCents(summary.spendCents);
}

